const watchState={active:false,paused:false,index:0,elapsed:0,backup:null,failed:false,lastTrial:-1,lastFuture:-1};
function startWatch(){
 if(watchState.active||state.worker)return;
 watchState.backup={case:state.case,p:state.p,playing:state.playing,search:state.search,future:state.future,polygon:state.polygon,custom:state.custom,recipe:formValues(),mode:scene.mode,compare:$('compare').checked,ensemble:$('ensemble-toggle').checked,forces:$('forces').checked,auto:scene.auto,hash:location.hash,progress:$('compute-progress').textContent,result:$('result-settings').textContent,viewResult:$('view-result').hidden};
 closeTour();watchState.active=true;watchState.paused=false;document.body.classList.add('watching');$('watch-panel').hidden=false;
 document.querySelector('.lab').setAttribute('role','dialog');document.querySelector('.lab').setAttribute('aria-modal','true');document.querySelector('.lab').setAttribute('aria-label','Watch the lab: hands-free demonstration');
 document.querySelectorAll('.masthead,.experiment-nav,.evidence-section,.answer-section,footer,.inspector,.transport,.stage-options,.view-buttons,#viewport').forEach(el=>el.inert=true);
 $('watch-pause').textContent='Pause';enterWatchChapter(0);$('watch-pause').focus({preventScroll:true});
}
function enterWatchChapter(index){
 if(index>=watchChapters.length){stopWatch();toast('Demonstration complete. Your experiment is restored.');return;}
 const c=watchChapters[index];watchState.index=index;watchState.elapsed=0;watchState.failed=false;watchState.lastTrial=-1;watchState.lastFuture=-1;state.search=7;state.future=0;state.polygon=c.polygon||3;$('polygon-count').value=state.polygon;$('future').value=0;
 choose(c.case);playState(false);setView(c.view||'orbit');$('compare').checked=!!c.compare;$('forces').checked=!!c.forces;$('ensemble-toggle').checked=!!c.ensemble;state.p=c.from;renderSystem();updateSearch();scene.auto=!reduced;scene.controls.enabled=false;
 if(c.inspect)bodyDetails(0);
 $('watch-chapter').textContent=`${String(index+1).padStart(2,'0')} / ${watchChapters.length} · WATCH THE LAB`;$('watch-title').textContent=c.title;$('watch-copy').textContent=c.copy;
 if(c.live){state.custom=null;renderSystem();$('stage-status').textContent='Calculating new orbit · reference shown';applyRecipe(c.recipe);run();}
 if(c.evidence&&!state.custom){watchState.failed=true;$('watch-copy').textContent='This device could not finish the live calculation. The app reports that failure rather than inventing a result. Preset experiments remain available.';}
 updateWatchFact();updateWatchProgress();
}
function updateWatchProgress(){const elapsed=watchChapters.slice(0,watchState.index).reduce((sum,c)=>sum+c.duration,0)+watchState.elapsed,total=watchChapters.reduce((sum,c)=>sum+c.duration,0),pct=Math.min(100,elapsed/total*100);$('watch-fill').style.width=pct+'%';$('watch-progress').setAttribute('aria-valuenow',Math.round(pct));$('watch-progress').setAttribute('aria-valuetext',`Chapter ${watchState.index+1} of ${watchChapters.length}`);}
function updateWatchFact(){const c=watchChapters[watchState.index];let fact;
 if(state.worker)fact=$('compute-progress').textContent;
 else if(watchState.failed)fact='Live calculation unavailable on this run · continuing with the demonstration';
 else if(c.search)fact=`Trial ${state.search+1} of 8 · return error ${sci(currentSearch().diagnostics.objectiveNorm)}`;
 else if(c.ensemble)fact=`Future ${state.future+1} of 8 · final separation growth ${$('growth').textContent}`;
 else if(c.case==='chaos')fact=`At t = 40: ${Math.round(data.chaos.diagnostics.separation.at(-1)/data.chaos.diagnostics.separation[0]).toLocaleString()}× growth · both main trajectories checked`;
 else if(c.case==='symmetry')fact=`Numerical vs exact position error: ${sci(current.diagnostics.maxNumericalError)} units`;
 else if(c.case==='custom'&&state.custom)fact=`Tighter-run disagreement ${sci(state.custom.diagnostics.maxNumericalError)} units · energy change ${sci(state.custom.diagnostics.maxEnergyDrift)}${state.custom.diagnostics.relativeDisagreement>.001?' · LOW NUMERICAL AGREEMENT':''}`;
 else if(c.view==='time')fact='Vertical axis = elapsed time · the physical orbit remains planar';
 else if(c.inspect)fact='Body 1 mass = 1 · arrows show direction only · G = 1';
 else fact='Known figure-eight orbit · computed and independently checked';
 $('watch-fact').textContent=fact;
}
function tickWatch(dt){
 if(!watchState.active||watchState.paused)return;
 const c=watchChapters[watchState.index];playStateSilent();
 if(c.live&&state.worker){scene.auto=!reduced;updateWatchFact();return;}
 if(c.live&&!state.custom&&!watchState.failed){watchState.failed=true;$('watch-copy').textContent='The live calculation could not finish on this device. The app reports the failure and continues; no replacement result is presented as a successful calculation.';}
 watchState.elapsed+=dt;const fraction=Math.min(1,watchState.elapsed/c.duration);
 if(c.search){const trial=Math.min(7,Math.floor(fraction*8));if(trial!==watchState.lastTrial){watchState.lastTrial=trial;setSearch(trial);}}
 if(c.ensemble){const future=Math.min(7,Math.floor(fraction*8));if(future!==watchState.lastFuture){watchState.lastFuture=future;state.future=future;$('future').value=future;renderSystem(false);}}
 state.p=c.from+(c.to-c.from)*fraction;updateProgress();updateWatchFact();updateWatchProgress();
 if(watchState.elapsed>=c.duration)enterWatchChapter(watchState.index+1);
}
function playStateSilent(){state.playing=false;state.searchPlaying=false;}
function pauseWatch(){if(!watchState.active)return;watchState.paused=!watchState.paused;scene.auto=!watchState.paused&&!reduced;$('watch-pause').textContent=watchState.paused?'Resume':'Pause';}
function stopWatch(restore=true){
 if(!watchState.active)return;const b=watchState.backup;if(state.worker)finishWorker();watchState.active=false;watchState.paused=false;document.body.classList.remove('watching');$('watch-panel').hidden=true;scene.auto=false;scene.controls.enabled=true;
 const lab=document.querySelector('.lab');lab.removeAttribute('role');lab.removeAttribute('aria-modal');lab.setAttribute('aria-label','Gravity laboratory');document.querySelectorAll('.masthead,.experiment-nav,.evidence-section,.answer-section,footer,.inspector,.transport,.stage-options,.view-buttons,#viewport').forEach(el=>el.inert=false);
 state.custom=b.custom;applyRecipe(b.recipe);$('compute-progress').textContent=b.progress;$('result-settings').textContent=b.result;$('view-result').hidden=b.viewResult;
 if(restore){state.search=b.search;state.future=b.future;state.polygon=b.polygon;$('polygon-count').value=b.polygon;$('future').value=b.future;choose(b.case);setView(b.mode);$('compare').checked=b.compare;$('ensemble-toggle').checked=b.ensemble;$('forces').checked=b.forces;state.p=b.p;renderSystem();updateSearch();scene.auto=b.auto;$('camera-drift').setAttribute('aria-pressed',b.auto);playState(b.playing);history.replaceState(null,'',b.hash||location.pathname);}
 $('watch').focus({preventScroll:true});
}

function bind(){
 $('watch').addEventListener('click',startWatch);$('watch-pause').addEventListener('click',pauseWatch);$('watch-exit').addEventListener('click',()=>stopWatch());
 document.addEventListener('keydown',e=>{if(!watchState.active)return;if(e.key==='Escape'){e.preventDefault();stopWatch();}if(e.key==='Tab'){const first=$('watch-pause'),last=$('watch-exit');if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}if(e.code==='Space'&&!['BUTTON','INPUT','SELECT'].includes(e.target.tagName)){e.preventDefault();pauseWatch();}});
 document.querySelector('.stage-column').appendChild($('tour-card'));
 const coarse=matchMedia('(pointer:coarse)').matches;if(coarse){scene.controls.enableRotate=false;scene.controls.enablePan=false;}$('touch-rotate').addEventListener('click',()=>{const enabled=$('touch-rotate').getAttribute('aria-pressed')!=='true';$('touch-rotate').setAttribute('aria-pressed',enabled);$('touch-rotate').textContent='Rotate: '+(enabled?'on':'off');$('viewport').classList.toggle('rotating',enabled);scene.controls.enableRotate=enabled;scene.controls.enablePan=enabled;});
 $('view-result').addEventListener('click',()=>{document.querySelector('.stage-column').scrollIntoView({behavior:reduced?'instant':'smooth'});scene.renderer.domElement.focus({preventScroll:true});});
 $('custom-controls').addEventListener('input',()=>{$('result-settings').textContent='Settings changed. Calculate to update the displayed orbit.';});
 $('evidence-chart').addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();if(state.case==='figure8'){stopSearch();setSearch(e.key==='Home'?0:e.key==='End'?7:state.search+(e.key==='ArrowRight'?1:-1));}else{state.p=e.key==='Home'?0:e.key==='End'?1:Math.max(0,Math.min(1,state.p+(e.key==='ArrowRight'?.01:-.01)));playState(false);updateProgress();}});
 document.addEventListener('keydown',e=>{if(e.key==='Escape'&&state.tour>=0)closeTour();});
 window.addEventListener('hashchange',()=>{if(watchState.active)stopWatch(false);closeTour();restoreLink();});
 document.querySelectorAll('button[aria-label]').forEach(b=>b.title=b.getAttribute('aria-label'));
 scene.renderer.domElement.addEventListener('webglcontextlost',e=>{e.preventDefault();if(watchState.active&&!watchState.paused)pauseWatch();playState(false);$('stage-status').textContent='Graphics paused — waiting for recovery';});scene.renderer.domElement.addEventListener('webglcontextrestored',()=>{$('stage-status').textContent=CASES[state.case].status;renderSystem();toast('Graphics recovered. Press Play to continue.');});
 document.querySelectorAll('[data-case]').forEach(b=>b.addEventListener('click',()=>{closeTour();choose(b.dataset.case);playState(!reduced);}));
 $('play').addEventListener('click',()=>{if(state.p>=1)state.p=0;playState(!state.playing);});$('restart').addEventListener('click',()=>{state.p=0;updateProgress();playState(!reduced);});$('timeline').addEventListener('input',e=>{playState(false);state.p=Number(e.target.value)/10000;updateProgress();});$('speed').addEventListener('change',e=>state.speed=Number(e.target.value));
 $('orbit-view').addEventListener('click',()=>setView('orbit'));$('time-view').addEventListener('click',()=>setView('time'));$('top-view').addEventListener('click',()=>scene.resetCamera(true));$('reset-view').addEventListener('click',()=>scene.resetCamera());$('camera-drift').addEventListener('click',()=>{scene.auto=!scene.auto;$('camera-drift').setAttribute('aria-pressed',scene.auto);});
 $('compare').addEventListener('change',()=>{scene.showCompare=$('compare').checked;updateProgress();});$('forces').addEventListener('change',()=>{scene.showForces=$('forces').checked;updateProgress();});$('ensemble-toggle').addEventListener('change',()=>{scene.showEnsemble=$('ensemble-toggle').checked;updateProgress();});
 $('search-step').addEventListener('input',e=>{stopSearch();setSearch(Number(e.target.value));});$('search-play').addEventListener('click',()=>{state.searchPlaying=!state.searchPlaying;if(state.searchPlaying){state.searchClock=0;setSearch(0);state.p=1;playState(false);updateProgress();}$('search-play').innerHTML=`<i data-lucide="${state.searchPlaying?'pause':'play'}"></i>${state.searchPlaying?'Pause search':'Watch search'}`;icons();});
 $('future').addEventListener('input',e=>{state.future=Number(e.target.value);$('compare').checked=true;renderSystem(false);});$('jump-divergence').addEventListener('click',()=>{state.p=.72;$('compare').checked=true;scene.showCompare=true;updateProgress();playState(!reduced);});$('polygon-count').addEventListener('change',e=>{state.polygon=Number(e.target.value);state.p=0;renderSystem();});
 $('break-symmetry').addEventListener('click',()=>{if(state.worker)finishWorker();choose('custom');$('starting-system').value=state.polygon===3?'triangle':'ring';$('duration').value='6.33';$('mass').value='1.1';$('velocity').value='100';$('lift').value='.12';$('kick').value='0';$('lift-value').textContent='0.12';$('velocity-value').textContent='100%';$('kick-value').textContent='0.000';run();});
 $('velocity').addEventListener('input',e=>$('velocity-value').textContent=e.target.value+'%');$('kick').addEventListener('input',e=>$('kick-value').textContent=Number(e.target.value).toFixed(3));$('lift').addEventListener('input',e=>$('lift-value').textContent=Number(e.target.value).toFixed(2));$('custom-controls').addEventListener('submit',e=>{e.preventDefault();run();});$('cancel-run').addEventListener('click',()=>{finishWorker();$('compute-progress').textContent='Calculation cancelled.';});
 $('body-close').addEventListener('click',()=>$('selected-body').hidden=true);
 const openMethod=()=>$('method-dialog').showModal();$('method-open').addEventListener('click',openMethod);$('evidence-method').addEventListener('click',openMethod);$('method-close').addEventListener('click',()=>$('method-dialog').close());$('method-dialog').addEventListener('click',e=>{if(e.target===$('method-dialog')){const r=$('method-dialog').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('method-dialog').close();}});
 $('tour').addEventListener('click',()=>tourStep(0));$('tour-next').addEventListener('click',()=>tourStep(state.tour+1));$('tour-prev').addEventListener('click',()=>tourStep(state.tour-1));$('tour-close').addEventListener('click',closeTour);
 $('fullscreen').addEventListener('click',async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.querySelector('.stage-column').requestFullscreen();}catch{toast('Fullscreen is unavailable in this browser.');}});
 $('share').addEventListener('click',async()=>{const url=new URL(location.href);url.hash=encodeURIComponent(JSON.stringify({v:1,case:state.case,p:Math.round(state.p*10000)/10000,search:state.search,future:state.future,polygon:state.polygon,view:scene.mode,compare:$('compare').checked,ensemble:$('ensemble-toggle').checked,recipe:state.case==='custom'?formValues():undefined}));try{await navigator.clipboard.writeText(url.href);toast('Link copied with these experiment settings.');}catch{if(navigator.share){try{await navigator.share({title:'Gravity, Unscripted',url:url.href});}catch{}}else toast('Share this page using the address in your browser.');}});
 $('evidence-chart').addEventListener('pointerdown',e=>{const box=$('evidence-chart').getBoundingClientRect(),f=Math.max(0,Math.min(1,(e.clientX-box.left-plot.left)/(plot.right-plot.left)));if(state.case==='figure8'){stopSearch();setSearch(Math.round(f*7));}else{state.p=f;playState(false);updateProgress();}});
 new ResizeObserver(()=>{updateEvidence();if(state.case==='figure8')updateSearch();}).observe($('evidence-chart'));
 document.addEventListener('keydown',e=>{if(e.code==='Space'&&e.target===scene.renderer.domElement&&!$('method-dialog').open){e.preventDefault();if(state.p>=1)state.p=0;playState(!state.playing);}});
}
function animate(now){const dt=prev?Math.min((now-prev)/1000,.06):0;prev=now;if(watchState.active&&!document.hidden)tickWatch(dt);if(!watchState.active&&state.playing&&current&&!document.hidden){state.p+=dt*state.speed/26;if(state.p>=1){state.p=1;playState(false);}updateProgress();}if(!watchState.active&&state.searchPlaying&&!document.hidden){state.searchClock+=dt;if(state.searchClock>1.3){state.searchClock=0;if(state.search<7)setSearch(state.search+1);else{state.searchPlaying=false;$('search-play').innerHTML='<i data-lucide="play"></i>Watch again';icons();}}}if(!document.hidden)scene?.render(dt);requestAnimationFrame(animate);}
try{
 const responses=await Promise.all(['/trajectories.json','/search.json','/ensemble.json'].map(async p=>{const r=await fetch(p,{signal:AbortSignal.timeout(20000)});if(!r.ok)throw new Error('The trajectory data did not load.');return r.json();}));data=Object.fromEntries(responses[0].scenarios.map(s=>[s.id,s]));search=responses[1];ensemble=responses[2];
 scene=new GravityScene($('viewport'),bodyDetails);bind();restoreLink();updateSearch();if(!sharedRecipe)playState(!reduced);icons();$('loading')?.remove();$('watch').disabled=false;requestAnimationFrame(animate);
}catch(e){$('stage-status').textContent='Unable to open the 3D view';let fallback=$('loading');if(!fallback){fallback=document.createElement('div');fallback.className='load-message';$('viewport').appendChild(fallback);}fallback.textContent='The laboratory could not load. Check your connection and WebGL support, then reload. The original calculations are available below.';const retry=document.createElement('button');retry.textContent='Reload laboratory';retry.onclick=()=>location.reload();fallback.appendChild(retry);console.error(e);}
